-- Built In rotation text: each key is the rotation ID plus .Name or .Description.
if GetLocale() ~= "zhCN" then return end
local addon_name = ...
local host = RotationMasterBuiltIns
local L = LibStub("AceLocale-3.0"):GetLocale(host and host.localeName or addon_name:match("^(.-)_[^_]+$") or addon_name)

L["rm.era.warrior.dps.Name"] = "近战 DPS"
L["rm.era.warrior.dps.Description"] = "1–60 级，武器和狂怒，以及所有不在防御姿态的战士，也适用于专家模式和自给自足服务器；综合 模拟器、Icy Veins 和 Wowhead。冲锋拉怪，对远处的目标使用拦截，有三个或更多敌人与你交战时使用旋风斩（学会前为雷霆一击），然后低于 20% 时斩杀优先，对没有破甲的首领叠满五层破甲攻击，嗜血，致死打击，拥有强化猛击时在挥击后立即使用猛击（按双手武器设置；可在复制的循环中修改），保留主要打击所需怒气的同时使用旋风斩，压制，学会主要打击之前使用撕裂，对生命值充足的目标使用破甲攻击，怒气接近上限时使用断筋。提醒：战斗怒吼、40 点怒气起使用英勇打击（升级期间 20 点）、对怪群使用顺劈斩、血性狂暴、横扫攻击、死亡之愿（首领：最后 30 秒）、配合死亡之愿使用鲁莽、拳击或盾击。破胆怒吼和反击风暴列为关闭状态，供专家模式紧急情况使用；姿态切换由你自己掌控。"
L["rm.era.warrior.protection.Name"] = "坦克"
L["rm.era.warrior.protection.Description"] = "只要你处于防御姿态就会选用（防护、狂怒防护或双手武器坦克）；综合 Icy Veins 和 MaxDps。四个或更多敌人时：用挫志怒吼和战斗怒吼制造仇恨。然后是复仇、盾牌猛击、嗜血、破甲攻击叠到五层、对精英使用挫志怒吼、以破甲攻击作为填充，以及在盾牌猛击或嗜血之前使用撕裂。盾牌猛击和盾牌格挡仅在装备盾牌时使用。提醒：战斗怒吼、目标攻击你时使用盾牌格挡、血性狂暴、50 点怒气起使用英勇打击和顺劈斩、盾击、破釜沉舟。嘲讽、盾墙和死亡之愿列为关闭状态；为斩杀切换战斗姿态（由 DPS 内置循环接管）和挑战怒吼由你自己掌控。"
L["rm.era.warrior.protection.icyveins.Name"] = "坦克，战斗怒吼仇恨（Icy Veins）"
L["rm.era.warrior.protection.icyveins.Description"] = "Icy Veins 的“不破甲”坦克循环，适用于有四名或更多玩家能受到你怒吼影响的队伍（第 5 阶段战斗怒吼起），是推荐的坦克内置循环的替代方案，默认关闭：启用它并禁用那个，或提高它的优先级。保持挫志怒吼，复仇，盾牌猛击或嗜血，然后以战斗怒吼代替破甲攻击作为仇恨填充；盾牌猛击和盾牌格挡仅在装备盾牌时使用。提醒与推荐的坦克循环相同；在一群敌人中专注单个目标时请换回破甲攻击。"
L["rm.forever.warrior.dps.Name"] = "武器和狂怒（Icy Veins）"
L["rm.forever.warrior.dps.Description"] = "武器和狂怒近战，适用于 1 至 60 级，也是所有不在防御姿态的战士的默认循环。永久服中怒气稀缺且对插件隐藏，因此只在致死打击或嗜血恢复期间才把怒气花在其他技能上，以此攒怒气：冲锋拉怪，乘胜追击，拦截，对精英、首领或组队时（在斩杀范围内）使用斩杀，旋风斩或雷霆一击，怪群时挫志怒吼和猛击，对巨人和龙类使用穿刺打击，学会嗜血前使用撕裂，压制，致死打击，嗜血，然后旋风斩，站立不动时猛击，两层破甲攻击（对精英叠五层）。提醒：战斗怒吼、血性狂暴、打断、主要打击恢复期间的英勇打击、怪群时的顺劈斩、横扫攻击、死亡之愿和狂暴之怒；鲁莽和反击风暴已列出但默认关闭。由你自己掌控：姿态切换、断筋和消耗品。"
L["rm.forever.warrior.dps.warcrafttavern.Name"] = "武器和狂怒，倾泻怒气（Warcraft Tavern）"
L["rm.forever.warrior.dps.warcrafttavern.Description"] = "Warcraft Tavern 用于小队和团队的始终倾泻怒气列表：先叠五层破甲攻击，目标低于 20% 时斩杀优先于一切，压制，学会嗜血前使用撕裂，致死打击，嗜血，旋风斩，穿刺打击冷却完毕即用，选了强化猛击后使用猛击；只要负担得起就使用英勇打击或顺劈斩（永久服中怒气是隐藏的，因此没有 60 怒气的阈值，也没有怒气有余时的断筋），鲁莽冷却完毕即用并同时使用死亡之愿。如果你在小队中游戏，不需要在两次拉怪之间保留怒气，请选择它而不是 Icy Veins 内置循环。它是推荐的近战 DPS 内置循环的替代方案，默认关闭：启用它并禁用那个，或提高它的优先级。"
L["rm.forever.warrior.protection.Name"] = "防护（Icy Veins）"
L["rm.forever.warrior.protection.Description"] = "10 至 60 级，只要你处于防御姿态就作为坦克循环。冲锋拉怪（拥有先锋后可在防御姿态下冲锋），乘胜追击，两个或更多敌人时雷霆一击冷却完毕即用、挫志怒吼、盾牌猛击、复仇和撕裂。单个目标时：盾牌猛击、复仇、挫志怒吼、撕裂、破甲攻击（对精英叠五层），对危险目标使用雷霆一击。提醒：战斗怒吼、血性狂暴、盾击、你持有目标仇恨时的盾牌格挡、盾牌猛击和复仇都在恢复时的英勇打击，怪群时的顺劈斩；嘲讽和盾墙已列出但默认关闭。在永久服上怒气、生命值和目标的法力值对插件隐藏，因此怒气阈值、施法者和破釜沉舟由你自己决定。由你自己掌控：学会先锋之前切换到战斗姿态冲锋、嘲讽其他敌人以及拉回跑掉的敌人。"
L["rm.forever.warrior.protection.warcrafttavern.Name"] = "防护，保持减益（Warcraft Tavern）"
L["rm.forever.warrior.protection.warcrafttavern.Description"] = "Warcraft Tavern 的坦克顺序：先在每个目标上保持雷霆一击、挫志怒吼和五层破甲攻击，然后是复仇、撕裂，最后是盾牌猛击，只要负担得起就使用英勇打击或顺劈斩（永久服中怒气是隐藏的，因此没有 60 怒气的阈值）。没有盾牌格挡或防御提醒。如果你更想先保持减益效果，请选择它而不是 Icy Veins 坦克内置循环。它是推荐的防护内置循环的替代方案，默认关闭：启用它并禁用那个，或提高它的优先级。"
L["rm.mop.warrior.arms.Name"] = "推荐"
L["rm.mop.warrior.arms.Description"] = "推荐武器专精使用，适用于 10 至 90 级，在武器专精中选用。以冲锋开场，离开目标时再次冲锋获取怒气。巨人打击缺失或即将结束时使用巨人打击，致死打击，巨人打击窗口内使用风暴之锤，窗口外使用巨龙怒吼和剑刃风暴。目标生命值低于 20% 时：在窗口内、怒气达到 100 或为保持猝死时使用斩杀，血之气息触发时使用压制。否则在窗口内使用猛击，四层时使用压制，怒气达到 100 时使用猛击，压制，猛击。有两个或更多敌人与你交战时加入横扫攻击、为重伤使用雷霆一击、剑刃风暴和巨龙怒吼。生命值低于 70% 时使用乘胜追击；为获取怒气使用战斗怒吼。提醒：没有怒吼时施放怒吼、战斗姿态、狂暴之怒、长时间战斗中配合巨人打击使用鲁莽、天神下凡和浴血奋战、颅骨战旗、怒气有余时使用英勇打击或顺劈斩、窗口内使用英勇飞跃、拳击、生命值低时使用剑在人在和狂怒回复。碎裂投掷已列出但关闭。由你自己掌控：取消剑刃风暴、姿态切换和站位。"
L["rm.mop.warrior.arms.icyveins.Name"] = "为巨人打击攒怒气（Icy Veins）"
L["rm.mop.warrior.arms.icyveins.Description"] = "默认关闭。Icy Veins 和 Wowhead 的武器顺序：巨人打击窗口之外使用压制，仅在怒气高于 80 时使用猛击，把怒气留到窗口内，而不是用猛击作为填充。窗口内：致死打击、猛击、压制、英勇投掷。目标生命值低于 20% 时：巨人打击、致死打击、斩杀、压制、巨龙怒吼。两个敌人时使用横扫攻击，三个或更多时使用雷霆一击怪群列表。英勇打击或顺劈斩仅在怒气接近上限时使用。提醒与推荐的武器内置循环相同。启用它并禁用那个即可使用。"
L["rm.mop.warrior.fury.Name"] = "推荐"
L["rm.mop.warrior.fury.Description"] = "推荐狂怒专精使用，适用于 10 至 90 级，在狂怒专精中选用。以冲锋开场并用它获取怒气。攒够两层怒击充能后使用巨人打击（鲁莽期间一层即可），窗口即将结束时使用怒击，嗜血，巨人打击，风暴之锤，窗口外使用巨龙怒吼，使用鲁莽怒火（单手武器）时在此使用斩杀，嗜血冷却期间使用剑刃风暴，使用泰坦之握（双手武器）时在窗口外再使用一次怒击，斩杀，血脉贲张触发时使用狂风打击，怒击（为下一个窗口保留一层充能），狂风打击，英勇投掷，为获取怒气使用战斗怒吼。有两个或更多敌人与你交战时加入剑刃风暴、巨龙怒吼、为绞肉机使用旋风斩以及顺劈的怒击。提醒：没有怒吼时施放怒吼、战斗姿态、为激怒使用狂暴之怒、长时间战斗中配合巨人打击使用鲁莽、天神下凡和浴血奋战、颅骨战旗、怒气有余时使用英勇打击或顺劈斩、英勇飞跃、拳击以及生命值低时的防御技能。由你自己掌控：取消剑刃风暴。"
L["rm.mop.warrior.fury.icyveins.Name"] = "巨人打击期间使用冷却技能（Icy Veins）"
L["rm.mop.warrior.fury.icyveins.Description"] = "默认关闭。Icy Veins 的狂怒顺序在巨人打击窗口内优先使用剑刃风暴或巨龙怒吼，并在目标生命值低于 20% 时把斩杀排在嗜血之前。窗口之外：巨人打击、嗜血、怒击仅在两层充能时使用、血脉贲张触发时使用狂风打击、怒吼、狂风打击。四个或更多敌人时：为激怒使用嗜血、用旋风斩叠到三层绞肉机、怒击。英勇打击或顺劈斩仅在怒气接近上限时使用。提醒与推荐的狂怒内置循环相同。启用它并禁用那个即可使用。"
L["rm.mop.warrior.protection.Name"] = "推荐"
L["rm.mop.warrior.protection.Description"] = "坦克循环，适用于 10 至 90 级，在防护专精中选用。用冲锋或英勇投掷拉怪。对精英和首领用毁灭打击保持三层破甲，巨龙怒吼，剑刃风暴，三个敌人时使用震荡波，三个或更多时雷霆一击冷却完毕即用。然后用复仇消耗盾牌格挡剩下的最后怒气，盾牌猛击，坚守阵地触发时使用复仇，为重伤使用毁灭打击，生命值低于 60% 时使用乘胜追击，复仇，为虚弱打击使用雷霆一击，斩杀，风暴之锤，为获取怒气使用怒吼，以及毁灭打击（26 级前为破甲攻击）。提醒：防御姿态、没有怒吼时施放怒吼、盾牌格挡未生效时使用、受伤且怒气有余时使用盾牌屏障、最后通牒、激动触发或怒气接近上限时使用英勇打击或顺劈斩、挫志怒吼、狂暴之怒、狂怒回复、生命值低时使用破釜沉舟和盾墙、你的进攻冷却技能、拳击。嘲讽和英勇飞跃已列出但关闭。由你自己掌控：嘲讽谁，以及面对魔法伤害时选择盾牌格挡还是盾牌屏障。"
L["rm.mop.warrior.unspecialized.Name"] = "无专精"
L["rm.mop.warrior.unspecialized.Description"] = "适用于 1 至 9 级，或选择专精之前。以冲锋拉怪，乘胜追击，斩杀，30 点怒气时使用英勇打击；没有处于任何姿态时提醒你进入战斗姿态。"
L["rm.retail.warrior.arms.Name"] = "暴雪战斗辅助"
L["rm.retail.warrior.arms.Description"] = "推荐至暗之夜的武器专精使用。在战斗中，游戏现在会对插件隐藏怒气、撕裂、巨人打击、触发效果、冷却时间和生命值，因此它会显示暴雪自己的战斗辅助建议（一键循环），并在你施法或没有选中敌人时停止。提醒它未包含的内容：英勇打击（建议从不使用的核心按键）、战斗中的天神下凡和勇士之矛、拉怪间隙的战斗怒吼、对可打断的施法使用拳击（只在游戏允许读取该施法的场合亮起）、战斗中一就绪就使用的剑在人在（生命值在正式服中是隐藏的，因此何时使用由你自己决定）。"
L["rm.retail.warrior.arms.colossus.Name"] = "巨神兵参考（SimulationCraft）"
L["rm.retail.warrior.arms.colossus.Description"] = "仅供参考，默认关闭：来自 SimulationCraft 和 Icy Veins 的巨神兵施放顺序用致死打击积累巨人神力，并需要读取至暗之夜在战斗中隐藏的增益效果。以冲锋开场；两个或更多敌人时使用横扫攻击；巨人神力少于五层时使用致死打击；在巨人打击之前使用撕裂；破坏者；两层猝死时使用斩杀；巨人打击；勇士之矛；巨人打击期间且有巨人神力时使用崩摧；英勇打击；致死打击；斩杀；压制；撕裂剩余不足 5 秒时使用撕裂；两个或更多敌人时使用剑刃风暴；猛击。提醒：天神下凡、剑在人在、战斗怒吼、拳击。"
L["rm.retail.warrior.arms.slayer.Name"] = "屠戮者参考（SimulationCraft）"
L["rm.retail.warrior.arms.slayer.Description"] = "仅供参考，默认关闭：来自 SimulationCraft、Icy Veins 和 Wowhead 的屠戮者施放顺序需要读取怒气、撕裂、巨人打击、猝死和趁虚而入，而至暗之夜会在战斗中隐藏它们。以冲锋开场；面对两个或更多交战中的敌人时使用横扫攻击；撕裂即将结束时在巨人打击之前使用撕裂；在巨人打击之前使用破坏者；两层猝死时使用斩杀；巨人打击；巨人打击或天神下凡期间使用剑刃风暴；英勇打击；两层趁虚而入时使用压制；致死打击；斩杀；压制；撕裂剩余不足 5 秒时使用撕裂；猛击。提醒：巨人打击就绪时使用天神下凡、剑在人在、战斗怒吼、拳击。"
L["rm.retail.warrior.fury.Name"] = "暴雪战斗辅助"
L["rm.retail.warrior.fury.Description"] = "推荐至暗之夜的狂怒专精使用。显示暴雪的战斗辅助建议（暴怒、嗜血、怒击、斩杀、奥丁之怒和剑刃风暴），并在你施法或没有选中敌人时停止。提醒它未包含的内容：战斗中的鲁莽、天神下凡和勇士之矛、拉怪间隙的战斗怒吼、拳击、战斗中一就绪就使用的狂怒回复（生命值在正式服中是隐藏的，因此何时使用由你自己决定）。"
L["rm.retail.warrior.fury.slayer.Name"] = "屠戮者参考（SimulationCraft）"
L["rm.retail.warrior.fury.slayer.Description"] = "仅供参考，默认关闭：SimulationCraft 的屠戮者施放顺序需要读取激怒、鲁莽和猝死，而至暗之夜会在战斗中隐藏它们；怒气在正式服中是隐藏的，所以暴怒只等待自身的消耗。以冲锋开场；面对两个或更多交战中的敌人时为获得增益效果使用旋风斩；激怒即将结束时使用暴怒；鲁莽期间：暴怒，剑刃风暴，猝死触发时使用斩杀，奥丁之怒；碎甲猛击；浴血奋战；斩杀；奥丁之怒；怒击；暴怒；嗜血；旋风斩。提醒：鲁莽、天神下凡、狂怒回复、战斗怒吼、拳击。"
L["rm.retail.warrior.fury.thane.Name"] = "山丘领主参考（Icy Veins）"
L["rm.retail.warrior.fury.thane.Description"] = "仅供参考，默认关闭：来自 SimulationCraft 和 Icy Veins 的山丘领主施放顺序会穿插雷霆轰击，并需要读取至暗之夜在战斗中隐藏的增益效果。以冲锋开场；两个或更多敌人时为获得增益效果使用旋风斩；激怒缺失或即将结束时使用暴怒（怒气在正式服中是隐藏的，所以没有怒气达到 100 的暴怒）；鲁莽期间使用浴血奋战；两层时使用雷霆轰击；碎甲猛击；浴血奋战；鲁莽期间使用暴怒；天神下凡期间使用雷霆轰击；怒击；雷霆轰击；暴怒；嗜血；斩杀；奥丁之怒；雷霆一击；旋风斩。提醒与屠戮者参考循环相同。"
L["rm.retail.warrior.initial.Name"] = "暴雪战斗辅助"
L["rm.retail.warrior.initial.Description"] = "推荐在你选择专精之前使用（此时游戏报告的是战士的初始专精）。高亮暴雪战斗辅助建议的下一个法术，这是在至暗之夜的战斗中游戏仍允许插件读取的唯一循环建议；你施法或引导时它会等待。同时包含所有战士内置循环共用的提醒，每一项在你学会对应法术后生效。当你在 10 级选择专精后，该专精的内置循环会接管。"
L["rm.retail.warrior.protection.Name"] = "暴雪战斗辅助"
L["rm.retail.warrior.protection.Description"] = "推荐至暗之夜的防护专精使用。显示暴雪针对伤害和仇恨的战斗辅助建议，并在你施法或没有选中敌人时停止。该建议从不施放盾牌格挡或无视苦痛，因此只要它们可用且你的目标正在攻击你，两者都会作为提醒亮起；游戏会隐藏怒气，因此无视苦痛亮起的次数会比你实际需要的更多。其他提醒：战斗中的天神下凡、挫志怒吼和勇士之矛、战斗中一就绪就使用的盾墙和破釜沉舟（生命值在正式服中是隐藏的，因此何时使用由你自己决定）、在队伍中你的目标攻击其他人时使用嘲讽、拉怪间隙的战斗怒吼、拳击。"
L["rm.retail.warrior.protection.icyveins.Name"] = "参考（Icy Veins）"
L["rm.retail.warrior.protection.icyveins.Description"] = "仅供参考，默认关闭：Icy Veins 和 SimulationCraft 的施放顺序需要读取盾牌格挡、雷霆轰击和巨人神力，而至暗之夜会在战斗中隐藏它们；怒气和生命值在正式服中是隐藏的。以冲锋开场；破坏者；两层时使用雷霆轰击；巨人神力达到五层时使用崩摧；盾牌冲锋；雷霆轰击；盾牌猛击；雷霆一击；斩杀；复仇；毁灭打击。提醒：盾牌格挡增益效果消失且你正在坦克时使用盾牌格挡、无视苦痛、天神下凡、挫志怒吼、勇士之矛、战斗中一就绪就使用的盾墙和破釜沉舟、战斗怒吼、拳击。"
L["rm.sod.warrior.dps.Name"] = "近战 DPS（探索赛季）"
L["rm.sod.warrior.dps.Description"] = "探索赛季，1–60 级，符文在你铭刻后即会使用：双手武器、双持、角斗姿态和升级，以及所有不在防御姿态的探索赛季战士；综合 模拟器 第 6 阶段和 Wowhead 第 7/8 阶段。冲锋，乘胜追击，拦截，两个或更多敌人时使用旋风斩（学会前为雷霆一击），强烈猛击达到三层时使用猛击，保持撕裂，血涌触发时使用猛击（铭刻了精准计时时冷却完毕即用），嗜血，致死打击，盾牌猛击（装备盾牌时），压制；然后铭刻了迅捷打击时使用它（双手武器），否则使用旋风斩、怒击和毁灭打击（铭刻前为破甲攻击）；30 点怒气或猝死触发时使用斩杀；怒气接近上限时使用断筋。提醒：战斗怒吼和命令怒吼、50 点怒气起使用英勇打击（噬心狂怒让你激怒时总是使用）、顺劈斩、血性狂暴、暴怒、死亡之愿、鲁莽、横扫攻击、打断。狂暴之怒以及为血之气息短暂切换战斗姿态列为关闭状态。"
L["rm.sod.warrior.dps.icyveins.Name"] = "近战 DPS（探索赛季，Icy Veins）"
L["rm.sod.warrior.dps.icyveins.Description"] = "Icy Veins 的探索赛季狂怒和武器页面，是推荐的探索赛季近战 DPS 内置循环的替代方案，默认关闭：启用它并禁用那个，或提高它的优先级。低于 20% 或猝死触发时斩杀排在最前，血涌触发时使用猛击，嗜血或致死打击，旋风斩，压制，怒击，然后仅在怒气高于 60 时使用迅捷打击和断筋；不使用撕裂；仅在怒气高于 80 时使用英勇打击。提醒与推荐的内置循环相同。"
L["rm.sod.warrior.dps.wowhead.Name"] = "战斗预示者姿态切换（探索赛季，Wowhead）"
L["rm.sod.warrior.dps.wowhead.Description"] = "Wowhead 第 7/8 阶段针对战斗预示者之魂或 T1 六件套（Rotation Master 无法看到）的循环，是推荐的探索赛季近战 DPS 内置循环的替代方案，默认关闭：启用它并禁用那个，或提高它的优先级。切换姿态以保持预示增益效果，几乎一直使用英勇打击，然后是嗜血、血涌触发的猛击、旋风斩、怒击和断筋；不使用撕裂和压制。依赖它之前请先在游戏中确认切换时机。"
L["rm.sod.warrior.tank.Name"] = "坦克（探索赛季）"
L["rm.sod.warrior.tank.Description"] = "探索赛季的坦克，处于防御姿态时选用；综合 Wowhead 第 8 阶段和 模拟器。冲锋；两个或更多敌人时使用雷霆一击、震荡波、盾牌猛击、复仇、旋风斩和毁灭打击；然后防御者的决心缺失或即将结束时使用盾牌猛击，复仇，盾牌猛击，震荡波，斩杀，角斗士的狡诈达到五层时使用旋风斩，毁灭打击（铭刻前为破甲攻击），对精英使用挫志怒吼和雷霆一击，在盾牌猛击之前使用撕裂；盾牌猛击和盾牌格挡仅在装备盾牌时使用。提醒：战斗怒吼和命令怒吼、盾牌格挡、50 点怒气起使用英勇打击、55 点起使用顺劈斩、血性狂暴、暴怒、破釜沉舟、打断。嘲讽、盾墙、死亡之愿、鲁莽和反击风暴列为关闭状态；为斩杀切换角斗姿态由你自己掌控。"
L["rm.tbc.warrior.dps.icyveins.Name"] = "近战 DPS（Icy Veins）"
L["rm.tbc.warrior.dps.icyveins.Description"] = "1–70 级，武器或狂怒，遵循 Icy Veins。拉怪、提醒和升级步骤与 模拟器 版本相同，但有致死打击时斩杀排在最前，有嗜血时斩杀紧随其后，旋风斩接着使用且不保留怒气，断筋仅在怒气接近满时使用。猛击时机、姿态切换和狂暴之怒由你自己掌控。它是推荐的 模拟器 近战 DPS 内置循环的替代方案，默认关闭：启用它并禁用那个，或提高它的优先级。"
L["rm.tbc.warrior.dps.simulator.Name"] = "近战 DPS（模拟器）"
L["rm.tbc.warrior.dps.simulator.Description"] = "1–70 级，武器或狂怒。冲锋拉怪，然后是乘胜追击、拦截、暴怒，两个或更多敌人与你交战时使用旋风斩（学会前为雷霆一击）。拥有嗜血或致死打击时：使用该打击，怒气有余时旋风斩，斩杀，压制。学会它们之前：旋风斩、斩杀、压制、撕裂。多余的怒气用于毁灭打击或破甲攻击，然后是断筋。会提醒你战斗怒吼、血性狂暴、以英勇打击或顺劈斩消耗怒气、横扫攻击、死亡之愿、鲁莽以及打断。猛击时机、姿态切换和狂暴之怒由你自己掌控。"
L["rm.tbc.warrior.protection.icyveins.Name"] = "坦克（Icy Veins）"
L["rm.tbc.warrior.protection.icyveins.Description"] = "10–70 级，处于防御姿态时选用，遵循 Icy Veins。盾牌猛击、复仇，然后是毁灭打击或破甲攻击，学会盾牌猛击之前在战斗开始时使用撕裂。怪群时：雷霆一击，对精英使用挫志怒吼。只要目标正在攻击你且你装备了盾牌，就会提醒盾牌格挡。嘲讽和其他辅助技能由你自己掌控。它是推荐的 Wowhead 坦克内置循环的替代方案，默认关闭：启用它并禁用那个，或提高它的优先级。"
L["rm.tbc.warrior.protection.wowhead.Name"] = "坦克（Wowhead）"
L["rm.tbc.warrior.protection.wowhead.Description"] = "10–70 级，处于防御姿态时选用。盾牌猛击、复仇，对精英和首领保持雷霆一击和挫志怒吼，然后是毁灭打击或破甲攻击。怪群时：先雷霆一击和挫志怒吼。会提醒你对首领和高等级敌人使用盾牌格挡（需装备盾牌）、英勇打击或顺劈斩、战斗怒吼、血性狂暴、盾击，以及紧急时的破釜沉舟和盾墙。嘲讽和其他辅助技能由你自己掌控。"
